import { useCallback, useMemo, useState } from 'react';
import { useCedrosLogin } from '../context/useCedrosLogin';
import { ApiClient, handleApiError } from '../utils/apiClient';
import type { AuthError, AuthResponse } from '../types';
import {
  credentialToServerJson,
  parseCreationOptionsFromServer,
  parseRequestOptionsFromServer,
} from '../utils/webauthnJson';

type WebAuthnOptionsResponse = {
  challengeId: string;
  options: {
    publicKey: Record<string, unknown>;
  };
};

export interface UseWebAuthnReturn {
  isSupported: boolean;
  isLoading: boolean;
  error: AuthError | null;
  clearError: () => void;

  /**
   * Unified passkey flow: tries discoverable auth first, falls back to signup if no passkey exists.
   * @param accessCode Optional signup access code forwarded to the server when creating a new account.
   */
  continueWithPasskey: (accessCode?: string) => Promise<AuthResponse>;
  /** Start a server-managed WebAuthn authentication ceremony (login). */
  authenticatePasskey: (params?: { email?: string }) => Promise<AuthResponse>;
  /** Register a new passkey for the currently authenticated user. */
  registerPasskey: (params?: {
    label?: string;
  }) => Promise<{ credentialId: string; label?: string }>;
  /** Create a new account using a passkey (unauthenticated signup). */
  signupWithPasskey: (params?: {
    email?: string;
    name?: string;
    label?: string;
    /** Optional signup access code forwarded to the server. */
    accessCode?: string;
  }) => Promise<AuthResponse>;
}

function isWebAuthnAvailable(): boolean {
  if (typeof window !== 'undefined') {
    const hostname = window.location?.hostname;
    const isLocalhost =
      hostname === 'localhost' || hostname === '127.0.0.1' || hostname?.endsWith('.localhost');
    const isSecure = (window as unknown as { isSecureContext?: boolean }).isSecureContext === true;
    if (!isSecure && !isLocalhost) {
      return false;
    }
  }
  return (
    typeof window !== 'undefined' &&
    typeof window.PublicKeyCredential !== 'undefined' &&
    typeof navigator !== 'undefined' &&
    typeof navigator.credentials !== 'undefined'
  );
}

function isAuthErrorShape(err: unknown): err is AuthError {
  return (
    typeof err === 'object' &&
    err !== null &&
    'code' in err &&
    'message' in err &&
    typeof (err as AuthError).code === 'string' &&
    typeof (err as AuthError).message === 'string'
  );
}

function mapWebAuthnDomError(err: unknown): AuthError | null {
  if (!(err instanceof Error)) return null;
  // DOMExceptions inherit from Error in modern browsers.
  const name = err.name;

  // User cancelled, dismissed, timed out, or no available credential.
  if (name === 'NotAllowedError') {
    return { code: 'SERVER_ERROR', message: 'Passkey operation was cancelled or timed out' };
  }

  // Common for trying to create a credential that already exists (or unusable state).
  if (name === 'InvalidStateError') {
    return { code: 'VALIDATION_ERROR', message: 'Passkey is not available for this operation' };
  }

  // Thrown for non-secure contexts, or RP ID / origin mismatches.
  if (name === 'SecurityError') {
    return {
      code: 'VALIDATION_ERROR',
      message:
        'Passkeys require HTTPS and a correctly configured relying party (WEBAUTHN_RP_ID / WEBAUTHN_RP_ORIGIN)',
    };
  }

  return null;
}

/**
 * Server-managed WebAuthn (passkey) authentication + registration.
 *
 * - Login: /webauthn/auth/options -> navigator.credentials.get -> /webauthn/auth/verify
 * - Registration: /webauthn/register/options -> navigator.credentials.create -> /webauthn/register/verify
 */
export function useWebAuthn(): UseWebAuthnReturn {
  const { config, _internal } = useCedrosLogin();
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<AuthError | null>(null);

  const apiClient = useMemo(
    () =>
      new ApiClient({
        baseUrl: config.serverUrl,
        timeoutMs: config.requestTimeout,
        retryAttempts: config.retryAttempts,
        // Needed for authenticated registration endpoints when cookie auth is disabled
        getAccessToken: _internal?.getAccessToken,
      }),
    [_internal?.getAccessToken, config.serverUrl, config.requestTimeout, config.retryAttempts]
  );

  const clearError = useCallback(() => setError(null), []);

  const isSupported = isWebAuthnAvailable();

  const authenticatePasskey = useCallback(
    async (params?: { email?: string }): Promise<AuthResponse> => {
      if (!isSupported) {
        const err: AuthError = {
          code: 'VALIDATION_ERROR',
          message: 'Passkeys are not supported in this browser',
        };
        setError(err);
        throw err;
      }

      setIsLoading(true);
      setError(null);

      try {
        const optionsResponse = await apiClient.post<WebAuthnOptionsResponse>(
          '/webauthn/auth/options',
          { email: params?.email }
        );

        const publicKey = parseRequestOptionsFromServer(optionsResponse.options);

        const assertion = (await navigator.credentials.get({
          publicKey,
        })) as PublicKeyCredential | null;

        if (!assertion) {
          throw new Error('Passkey authentication returned no credential');
        }

        const data = await apiClient.post<AuthResponse>('/webauthn/auth/verify', {
          challengeId: optionsResponse.challengeId,
          credential: credentialToServerJson(assertion),
        });

        config.callbacks?.onLoginSuccess?.(data.user, 'webauthn');
        _internal?.handleLoginSuccess(data.user, data.tokens);

        return data;
      } catch (err) {
        const domMapped = mapWebAuthnDomError(err);
        const authError = domMapped ?? handleApiError(err, 'Unable to sign in with passkey. Please try again.');
        setError(authError);
        throw authError;
      } finally {
        setIsLoading(false);
      }
    },
    [apiClient, config.callbacks, _internal, isSupported]
  );

  const registerPasskey = useCallback(
    async (params?: { label?: string }): Promise<{ credentialId: string; label?: string }> => {
      if (!isSupported) {
        const err: AuthError = {
          code: 'VALIDATION_ERROR',
          message: 'Passkeys are not supported in this browser',
        };
        setError(err);
        throw err;
      }

      setIsLoading(true);
      setError(null);

      try {
        const optionsResponse = await apiClient.post<WebAuthnOptionsResponse>(
          '/webauthn/register/options',
          {}
        );

        const publicKey = parseCreationOptionsFromServer(optionsResponse.options);

        const created = (await navigator.credentials.create({
          publicKey,
        })) as PublicKeyCredential | null;

        if (!created) {
          throw new Error('Passkey registration returned no credential');
        }

        const result = await apiClient.post<{
          success: boolean;
          credentialId: string;
          label?: string;
        }>('/webauthn/register/verify', {
          challengeId: optionsResponse.challengeId,
          credential: credentialToServerJson(created),
          label: params?.label,
        });

        if (!result.success) {
          throw new Error('Passkey registration failed');
        }

        return { credentialId: result.credentialId, label: result.label };
      } catch (err) {
        const domMapped = mapWebAuthnDomError(err);
        const authError = domMapped ?? handleApiError(err, 'Unable to register passkey. Please try again.');
        setError(authError);
        throw authError;
      } finally {
        setIsLoading(false);
      }
    },
    [apiClient, isSupported]
  );

  const signupWithPasskey = useCallback(
    async (params?: { email?: string; name?: string; label?: string; accessCode?: string }): Promise<AuthResponse> => {
      if (!isSupported) {
        const err: AuthError = {
          code: 'VALIDATION_ERROR',
          message: 'Passkeys are not supported in this browser',
        };
        setError(err);
        throw err;
      }

      setIsLoading(true);
      setError(null);

      try {
        const optionsResponse = await apiClient.post<WebAuthnOptionsResponse>(
          '/webauthn/signup/options',
          {}
        );

        const publicKey = parseCreationOptionsFromServer(optionsResponse.options);

        const created = (await navigator.credentials.create({
          publicKey,
        })) as PublicKeyCredential | null;

        if (!created) {
          throw new Error('Passkey signup returned no credential');
        }

        const data = await apiClient.post<AuthResponse>('/webauthn/signup/verify', {
          challengeId: optionsResponse.challengeId,
          credential: credentialToServerJson(created),
          email: params?.email,
          name: params?.name,
          label: params?.label,
          referral: _internal?.getReferralCode?.() ?? undefined,
          access_code: params?.accessCode || undefined,
        });

        config.callbacks?.onLoginSuccess?.(data.user, 'webauthn');
        _internal?.handleLoginSuccess(data.user, data.tokens);

        return data;
      } catch (err) {
        const domMapped = mapWebAuthnDomError(err);
        const authError = domMapped ?? handleApiError(err, 'Unable to sign up with passkey. Please try again.');
        setError(authError);
        throw authError;
      } finally {
        setIsLoading(false);
      }
    },
    [apiClient, config.callbacks, _internal, isSupported]
  );

  // Unified flow that adapts to new vs returning users:
  //
  // - Returning users (localStorage hint): auth-first (get) → direct Touch ID
  // - New users (no hint): create-first (signup) → direct Touch ID
  //
  // Auth-first for new users shows a confusing QR/cross-device dialog (Chrome's
  // default when no local credential exists for a discoverable get request).
  // Create-first for returning users would show Touch ID for a create that the
  // server's excludeCredentials rejects, then another Touch ID for auth.
  const continueWithPasskey = useCallback(async (accessCode?: string): Promise<AuthResponse> => {
    if (!isSupported) {
      const err: AuthError = {
        code: 'VALIDATION_ERROR',
        message: 'Passkeys are not supported in this browser',
      };
      setError(err);
      throw err;
    }

    setIsLoading(true);
    setError(null);

    const hasPasskeyHint =
      typeof localStorage !== 'undefined' &&
      localStorage.getItem('cedros-passkey-registered') === '1';

    const markPasskeyRegistered = () => {
      try {
        localStorage.setItem('cedros-passkey-registered', '1');
      } catch {
        // localStorage might be unavailable (private browsing, etc.)
      }
    };

    if (hasPasskeyHint) {
      // Returning user: auth-first → direct Touch ID
      return continueWithPasskeyAuthFirst(markPasskeyRegistered, accessCode);
    }

    // New user: create-first → direct Touch ID
    return continueWithPasskeyCreateFirst(markPasskeyRegistered, accessCode);
  }, [apiClient, config.callbacks, _internal, isSupported]); // eslint-disable-line react-hooks/exhaustive-deps

  // Auth-first flow: credentials.get() → auth/verify, fallback to create
  const continueWithPasskeyAuthFirst = useCallback(
    async (markPasskeyRegistered: () => void, accessCode?: string): Promise<AuthResponse> => {
      try {
        const authOptions = await apiClient.post<WebAuthnOptionsResponse>(
          '/webauthn/auth/options',
          {}
        );
        const getKey = parseRequestOptionsFromServer(authOptions.options);

        const assertion = (await navigator.credentials.get({
          publicKey: getKey,
        })) as PublicKeyCredential | null;

        if (!assertion) {
          throw new Error('Passkey authentication returned no credential');
        }

        const data = await apiClient.post<AuthResponse>('/webauthn/auth/verify', {
          challengeId: authOptions.challengeId,
          credential: credentialToServerJson(assertion),
        });

        config.callbacks?.onLoginSuccess?.(data.user, 'webauthn');
        _internal?.handleLoginSuccess(data.user, data.tokens);
        markPasskeyRegistered();
        return data;
      } catch (authErr) {
        // Fall back to signup (create) only if no passkey exists at all.
        const shouldFallbackToCreate =
          authErr instanceof Error &&
          (authErr.name === 'NotAllowedError' || authErr.name === 'InvalidStateError');

        if (shouldFallbackToCreate) {
          return doPasskeySignup(markPasskeyRegistered, accessCode);
        }

        // Orphan passkey: exists on device but server doesn't recognize it.
        const isOrphanPasskey =
          typeof authErr === 'object' &&
          authErr !== null &&
          'isApiError' in authErr &&
          (authErr as { data?: { code?: string } }).data?.code === 'INVALID_CREDENTIALS';

        if (isOrphanPasskey) {
          const orphanError: AuthError = {
            code: 'INVALID_CREDENTIALS',
            message:
              'This passkey is not recognized. Please remove old passkeys for this site and try again, or sign in another way.',
          };
          setError(orphanError);
          throw orphanError;
        }

        const domMapped = mapWebAuthnDomError(authErr);
        const authError =
          domMapped ?? handleApiError(authErr, 'Unable to sign in with passkey. Please try again.');
        setError(authError);
        throw authError;
      } finally {
        setIsLoading(false);
      }
    },
    [apiClient, config.callbacks, _internal] // eslint-disable-line react-hooks/exhaustive-deps
  );

  // Create-first flow: credentials.create() → signup/verify, fallback to auth
  const continueWithPasskeyCreateFirst = useCallback(
    async (markPasskeyRegistered: () => void, accessCode?: string): Promise<AuthResponse> => {
      try {
        return await doPasskeySignup(markPasskeyRegistered, accessCode);
      } catch (createErr) {
        // If create fails with InvalidStateError, the user already has a passkey
        // registered on the server (exclude list matched). Fall back to auth.
        const shouldFallbackToAuth =
          createErr instanceof Error &&
          (createErr.name === 'InvalidStateError' || createErr.name === 'NotAllowedError');

        if (shouldFallbackToAuth) {
          return continueWithPasskeyAuthFirst(markPasskeyRegistered, accessCode);
        }

        // Surface the create error
        if (!isAuthErrorShape(createErr)) {
          const domMapped = mapWebAuthnDomError(createErr);
          const authError =
            domMapped ??
            handleApiError(createErr, 'Unable to create passkey. Please try again.');
          setError(authError);
          throw authError;
        }
        throw createErr;
      } finally {
        setIsLoading(false);
      }
    },
    [apiClient, config.callbacks, _internal] // eslint-disable-line react-hooks/exhaustive-deps
  );

  // Shared signup (create) logic used by both flows
  const doPasskeySignup = useCallback(
    async (markPasskeyRegistered: () => void, accessCode?: string): Promise<AuthResponse> => {
      const signupOptions = await apiClient.post<WebAuthnOptionsResponse>(
        '/webauthn/signup/options',
        {}
      );
      const createKey = parseCreationOptionsFromServer(signupOptions.options);

      const created = (await navigator.credentials.create({
        publicKey: createKey,
      })) as PublicKeyCredential | null;

      if (!created) {
        throw new Error('Passkey signup returned no credential');
      }

      const data = await apiClient.post<AuthResponse>('/webauthn/signup/verify', {
        challengeId: signupOptions.challengeId,
        credential: credentialToServerJson(created),
        referral: _internal?.getReferralCode?.() ?? undefined,
        access_code: accessCode || undefined,
      });

      config.callbacks?.onLoginSuccess?.(data.user, 'webauthn');
      _internal?.handleLoginSuccess(data.user, data.tokens);
      markPasskeyRegistered();
      return data;
    },
    [apiClient, config.callbacks, _internal]
  );

  return {
    isSupported,
    isLoading,
    error,
    clearError,
    continueWithPasskey,
    authenticatePasskey,
    registerPasskey,
    signupWithPasskey,
  };
}
